INSERT INTO `notification_templates` (`event_key`,`channel`,`provider`,`subject`,`body`,`is_active`) VALUES
('register','whatsapp','starsender',NULL,'Halo {{name}}! 👋\n\nSelamat datang di *{{app_name}}* 🎉\n\nAkun kamu sudah aktif. Silakan login di:\n{{login_url}}\n\n📧 Email login: {{email}}\n\nSalam,\nTim {{app_name}}',1),
('order_created','whatsapp','starsender',NULL,'Halo {{name}}! 🛒\n\nPesanan kamu di *{{app_name}}* sudah kami terima dan menunggu pembayaran.\n\n📋 No. Pesanan: *{{order_number}}*\n💳 Metode: {{payment_method}}\n💰 Total: *{{total}}*\n\nSelesaikan pembayaran di sini:\n{{invoice_url}}\n\nSalam,\nTim {{app_name}}',1),
('payment_success','whatsapp','starsender',NULL,'✅ *Pembayaran Berhasil!*\n\nHalo {{name}}, pembayaran kamu sudah kami konfirmasi. Terima kasih! 🙏\n\n📋 No. Pesanan: *{{order_number}}*\n💰 Total: *{{total}}*\n📅 Tanggal: {{paid_at}}\n\n🚀 Akses konten kamu di sini:\n{{member_url}}\n\n🧾 Lihat invoice:\n{{invoice_url}}\n\nTim {{app_name}}',1),
('access_activated','whatsapp','starsender',NULL,'🚀 *Akses Sudah Aktif!*\n\nHalo {{name}}, akses kamu untuk *{{product_name}}* sudah aktif sepenuhnya! 🎉\n\n📦 Pesanan: *{{order_number}}*\n\n▶️ Mulai akses konten sekarang:\n{{member_url}}\n\n🧾 Lihat invoice:\n{{invoice_url}}\n\nSelamat menikmati!\nTim {{app_name}}',1),
('public_checkout_welcome','whatsapp','starsender',NULL,'Halo {{name}}! 👋\n\nTerima kasih sudah membeli di *{{app_name}}* 🎉\nKami sudah otomatis membuatkan akun untukmu:\n\n📧 Email: {{email}}\n🔑 Password sementara: *{{temp_password}}*\n\nLogin lalu segera ganti passwordmu di:\n{{login_url}}\n\n🚀 Buka area member:\n{{member_url}}\n\nTim {{app_name}}',1),
('abandoned_cart','whatsapp','starsender',NULL,'Halo {{name}} 👋\n\nPesananmu untuk *{{product_name}}* ({{total}}) belum selesai nih.\n\nYuk lanjutkan pembayaran di sini:\n{{checkout_url}}\n\nKalau kamu sudah membayar, abaikan pesan ini ya. 🙏\n\nTim {{app_name}}',1),
('commission_approved','whatsapp','starsender',NULL,'💰 *Komisi Disetujui!*\n\nHalo {{name}}, komisi kamu sebesar *{{amount}}* dari pesanan {{order_number}} sudah disetujui dan siap dicairkan. 🎉\n\nAjukan pencairan di dashboard afiliasi:\n{{affiliate_url}}\n\nTim {{app_name}}',1),
('payout_processing','whatsapp','starsender',NULL,'⏳ *Pencairan Diproses*\n\nHalo {{name}}, permintaan pencairan komisimu sebesar *{{amount}}* sedang kami proses.\n\n🏦 Bank: {{bank_name}}\n🔢 No. Rekening: {{bank_account_no}}\n👤 A/N: {{bank_account_name}}\n\nKami kabari lagi begitu dana selesai ditransfer. 🙏\n\nTim {{app_name}}',1),
('payout_paid','whatsapp','starsender',NULL,'✅ *Pencairan Berhasil!*\n\nHalo {{name}}, komisi kamu sebesar *{{amount}}* sudah kami transfer ke rekening *{{bank_name}}*. 💸\n\nCek riwayat di dashboard afiliasi:\n{{affiliate_url}}\n\nTerima kasih sudah menjadi mitra kami! 🙏\n\nTim {{app_name}}',1),
('payout_rejected','whatsapp','starsender',NULL,'⚠️ *Pencairan Ditolak*\n\nHalo {{name}}, maaf permintaan pencairan sebesar *{{amount}}* belum dapat kami proses.\n\n📝 Alasan: {{reason}}\n\nSilakan periksa kembali data rekeningmu lalu ajukan ulang di:\n{{affiliate_url}}\n\nTim {{app_name}}',1),
('lead_captured','whatsapp','starsender',NULL,'Halo {{name}} 👋\n\nTerima kasih sudah mendaftar di *{{lead_magnet}}* 🎉\nAkses & info selanjutnya akan kami kirimkan ke sini ya.\n\nTim {{app_name}}',1),
('lead_admin_notify','whatsapp','starsender',NULL,'🔔 *Lead Baru Masuk!*\n\n👤 Nama: {{name}}\n📱 WA: {{whatsapp}}\n📧 Email: {{email}}\n📄 Form: {{lead_magnet}}\n\n{{app_name}}',1),
('register','email','mailketing','Selamat Datang di {{app_name}}! 🎉','<p>Halo <strong>{{name}}</strong>,</p><p>Akun kamu di <strong>{{app_name}}</strong> sudah berhasil dibuat. Selamat bergabung! 🎉</p><p>Gunakan email <strong>{{email}}</strong> untuk masuk ke dashboard kamu.</p><p style=\"text-align:center;margin:28px 0\"><a href=\"{{dashboard_url}}\" style=\"display:inline-block;background:{{brand_color}};color:#ffffff;text-decoration:none;padding:13px 32px;border-radius:10px;font-weight:700;font-size:15px\">Masuk ke Dashboard →</a></p><p style=\"font-size:13px;color:#8a94a6\">Jika kamu tidak merasa mendaftar, cukup abaikan email ini.</p>',1),
('order_created','email','mailketing','Pesanan Diterima — Menunggu Pembayaran','<p>Halo <strong>{{name}}</strong>,</p><p>Pesanan kamu sudah kami terima dan sedang menunggu pembayaran. ⏳</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f6f8fb;border-radius:12px;margin:16px 0\"><tr><td style=\"padding:12px 18px;font-size:14px;color:#64748b;text-align:left;border-bottom:1px solid #e9edf4;\">No. Pesanan</td><td style=\"padding:12px 18px;font-size:14px;color:#0f172a;font-weight:700;text-align:right;border-bottom:1px solid #e9edf4;\">{{order_number}}</td></tr><tr><td style=\"padding:12px 18px;font-size:14px;color:#64748b;text-align:left;border-bottom:1px solid #e9edf4;\">Metode Bayar</td><td style=\"padding:12px 18px;font-size:14px;color:#0f172a;font-weight:700;text-align:right;border-bottom:1px solid #e9edf4;\">{{payment_method}}</td></tr><tr><td style=\"padding:12px 18px;font-size:14px;color:#64748b;text-align:left;\">Total</td><td style=\"padding:12px 18px;font-size:14px;color:#0f172a;font-weight:700;text-align:right;\">{{total}}</td></tr></table><p style=\"text-align:center;margin:28px 0\"><a href=\"{{invoice_url}}\" style=\"display:inline-block;background:{{brand_color}};color:#ffffff;text-decoration:none;padding:13px 32px;border-radius:10px;font-weight:700;font-size:15px\">Lihat Invoice &amp; Bayar →</a></p>',1),
('payment_success','email','mailketing','Pembayaran Berhasil! ✅','<p>Halo <strong>{{name}}</strong>,</p><p>Pembayaran kamu sudah kami konfirmasi. Terima kasih! 🎉</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f6f8fb;border-radius:12px;margin:16px 0\"><tr><td style=\"padding:12px 18px;font-size:14px;color:#64748b;text-align:left;border-bottom:1px solid #e9edf4;\">No. Pesanan</td><td style=\"padding:12px 18px;font-size:14px;color:#0f172a;font-weight:700;text-align:right;border-bottom:1px solid #e9edf4;\">{{order_number}}</td></tr><tr><td style=\"padding:12px 18px;font-size:14px;color:#64748b;text-align:left;border-bottom:1px solid #e9edf4;\">Tanggal Bayar</td><td style=\"padding:12px 18px;font-size:14px;color:#0f172a;font-weight:700;text-align:right;border-bottom:1px solid #e9edf4;\">{{paid_at}}</td></tr><tr><td style=\"padding:12px 18px;font-size:14px;color:#64748b;text-align:left;\">Total Dibayar</td><td style=\"padding:12px 18px;font-size:14px;color:#0f172a;font-weight:700;text-align:right;\">{{total}}</td></tr></table><p style=\"text-align:center;margin:28px 0\"><a href=\"{{member_url}}\" style=\"display:inline-block;background:{{brand_color}};color:#ffffff;text-decoration:none;padding:13px 32px;border-radius:10px;font-weight:700;font-size:15px\">Akses Konten Sekarang →</a></p><p style=\"font-size:13px;color:#8a94a6\">Lihat invoice kamu: {{invoice_url}}</p>',1),
('access_activated','email','mailketing','Akses Kamu Sudah Aktif! 🚀','<p>Halo <strong>{{name}}</strong>,</p><p>Akses kamu untuk <strong>{{product_name}}</strong> sudah aktif sepenuhnya! 🎉</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f6f8fb;border-radius:12px;margin:16px 0\"><tr><td style=\"padding:12px 18px;font-size:14px;color:#64748b;text-align:left;border-bottom:1px solid #e9edf4;\">Produk</td><td style=\"padding:12px 18px;font-size:14px;color:#0f172a;font-weight:700;text-align:right;border-bottom:1px solid #e9edf4;\">{{product_name}}</td></tr><tr><td style=\"padding:12px 18px;font-size:14px;color:#64748b;text-align:left;\">No. Pesanan</td><td style=\"padding:12px 18px;font-size:14px;color:#0f172a;font-weight:700;text-align:right;\">{{order_number}}</td></tr></table><p style=\"text-align:center;margin:28px 0\"><a href=\"{{member_url}}\" style=\"display:inline-block;background:{{brand_color}};color:#ffffff;text-decoration:none;padding:13px 32px;border-radius:10px;font-weight:700;font-size:15px\">Mulai Belajar Sekarang →</a></p><p style=\"font-size:13px;color:#8a94a6\">Lihat invoice kamu: {{invoice_url}}</p>',1),
('abandoned_cart','email','mailketing','Pesananmu belum selesai, {{name}} 🛒','<p>Halo <strong>{{name}}</strong>,</p><p>Kamu sudah mulai memesan <strong>{{product_name}}</strong> seharga <strong>{{total}}</strong>, tapi pembayarannya belum selesai. 🛒</p><p style=\"text-align:center;margin:28px 0\"><a href=\"{{checkout_url}}\" style=\"display:inline-block;background:{{brand_color}};color:#ffffff;text-decoration:none;padding:13px 32px;border-radius:10px;font-weight:700;font-size:15px\">Selesaikan Pembayaran →</a></p><p style=\"font-size:13px;color:#8a94a6\">Atau buka tautan ini: {{checkout_url}}<br>No. Pesanan: {{order_number}}</p><p style=\"font-size:13px;color:#8a94a6\">Kalau kamu sudah membayar, abaikan email ini. 🙏</p>',1),
('commission_approved','email','mailketing','Komisi kamu disetujui! 💰','<p>Halo <strong>{{name}}</strong>,</p><p>Kabar baik! 🎉 Komisi kamu sebesar <strong>{{amount}}</strong> dari pesanan <strong>{{order_number}}</strong> sudah <strong>disetujui</strong> dan siap dicairkan.</p><p style=\"text-align:center;margin:28px 0\"><a href=\"{{affiliate_url}}\" style=\"display:inline-block;background:{{brand_color}};color:#ffffff;text-decoration:none;padding:13px 32px;border-radius:10px;font-weight:700;font-size:15px\">Ajukan Pencairan →</a></p><p style=\"font-size:13px;color:#8a94a6\">Atau buka dashboard afiliasi: {{affiliate_url}}</p>',1),
('payout_processing','email','mailketing','Pencairan kamu sedang diproses ⏳','<p>Halo <strong>{{name}}</strong>,</p><p>Permintaan pencairan komisimu sebesar <strong>{{amount}}</strong> sedang kami proses. ⏳</p><p style=\"background:#f6f8fb;border-radius:10px;padding:16px 20px;font-size:14px;color:#475569;line-height:1.9\">🏦 Bank: <strong>{{bank_name}}</strong><br>🔢 No. Rekening: <strong>{{bank_account_no}}</strong><br>👤 Atas Nama: <strong>{{bank_account_name}}</strong></p><p>Kami akan mengabari lagi begitu dana selesai ditransfer. 🙏</p><p style=\"font-size:13px;color:#8a94a6\">Cek status di dashboard afiliasi: {{affiliate_url}}</p>',1),
('payout_paid','email','mailketing','Pencairan komisimu berhasil! ✅','<p>Halo <strong>{{name}}</strong>,</p><p>Komisi kamu sebesar <strong>{{amount}}</strong> sudah berhasil kami transfer ke rekening <strong>{{bank_name}}</strong>. 💸</p><p style=\"text-align:center;margin:28px 0\"><a href=\"{{affiliate_url}}\" style=\"display:inline-block;background:{{brand_color}};color:#ffffff;text-decoration:none;padding:13px 32px;border-radius:10px;font-weight:700;font-size:15px\">Lihat Riwayat Komisi →</a></p><p>Terima kasih sudah menjadi mitra kami! 🙏</p>',1),
('payout_rejected','email','mailketing','Permintaan pencairan ditolak ⚠️','<p>Halo <strong>{{name}}</strong>,</p><p>Maaf, permintaan pencairan sebesar <strong>{{amount}}</strong> belum dapat kami proses. ⚠️</p><p style=\"background:#fef2f2;border-radius:10px;padding:16px 20px;font-size:14px;color:#b91c1c\">📝 Alasan: {{reason}}</p><p>Silakan periksa kembali data rekeningmu lalu ajukan pencairan ulang.</p><p style=\"text-align:center;margin:28px 0\"><a href=\"{{affiliate_url}}\" style=\"display:inline-block;background:{{brand_color}};color:#ffffff;text-decoration:none;padding:13px 32px;border-radius:10px;font-weight:700;font-size:15px\">Ajukan Ulang →</a></p>',1),
('lead_captured','email','mailketing','Terima kasih sudah daftar, {{name}}! 🎉','<p>Halo <strong>{{name}}</strong>,</p><p>Terima kasih sudah mendaftar di <strong>{{lead_magnet}}</strong>! 🎉</p><p>Akses dan informasi selanjutnya akan kami kirimkan ke kamu. Pantau terus email dan WhatsApp-mu ya. 📩</p>',1),
('public_checkout_welcome','email','mailketing','Akun kamu di {{app_name}} sudah siap! 🎉','<p>Halo <strong>{{name}}</strong>,</p><p>Terima kasih sudah melakukan pembelian di <strong>{{app_name}}</strong>! 🎉 Kami sudah otomatis membuatkan akun untukmu:</p><p style=\"background:#f6f8fb;border-radius:10px;padding:16px 20px;font-size:14px;color:#475569;line-height:1.9\">📧 Email: <strong>{{email}}</strong><br>🔑 Password sementara: <strong>{{temp_password}}</strong></p><p>Silakan login lalu segera ganti passwordmu demi keamanan. 🔒</p><p style=\"text-align:center;margin:28px 0\"><a href=\"{{login_url}}\" style=\"display:inline-block;background:{{brand_color}};color:#ffffff;text-decoration:none;padding:13px 32px;border-radius:10px;font-weight:700;font-size:15px\">Login Sekarang →</a></p><p style=\"font-size:13px;color:#8a94a6\">Buka area member: {{member_url}}</p>',1)
