-- Averion migration 1.1.34
-- Rapikan template notifikasi email dan WhatsApp
-- Perbaiki mojibake emoji, tambah emoji relevan, lengkapi placeholder per event
-- Idempoten via UNIQUE KEY uk_event_channel; hanya perbarui subject dan body,
-- provider dan is_active existing dipertahankan (butuh runner robust 1.1.27+)
ON DUPLICATE KEY UPDATE `subject`=VALUES(`subject`), `body`=VALUES(`body`);
